css:
.columns {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding: 24px;
  font-family: system-ui, sans-serif;
  font-size: 16px;
}

.sample {
  margin: 0;
  padding: 12px;
  border-radius: 8px;
  background-color: #fff7ed;
}

.tight {
  line-height: 1;
}

.normal {
  line-height: 1.5;
}

.loose {
  line-height: 2;
}
